import {readOfflineLicense} from './offline-license.js';
import {createHistorySettings} from './history-settings.js';
import {APP_VERSION} from './app-version.js';
import {readPreferences,savePreferences} from './system-settings-model.js';
const element=(tag,cls,text)=>{const e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined)e.textContent=text;return e};
const bytes=value=>Number.isFinite(value)?value<1048576?(value/1024).toFixed(1)+' KB':(value/1048576).toFixed(1)+' MB':'—';
export function createSystemSettings({icon,onKeys,onHelp,getStats,getCache,clearCache,getHistoryAccounts=()=>[],onPreferencesChange=()=>{}}){
 const dialog=element('dialog','system-settings-dialog');dialog.setAttribute('aria-labelledby','systemSettingsTitle');
 dialog.innerHTML=`<header class="system-settings-head"><div><span class="settings-head-icon"></span><h2 id="systemSettingsTitle">系统设置</h2><span class="settings-scope">全局设置</span></div><button type="button" class="icon-button settings-close" aria-label="关闭系统设置"></button></header>
 <div class="system-settings-layout"><nav class="system-settings-nav" aria-label="设置分类"></nav><div class="system-settings-content">
 <section data-settings-panel="appearance" hidden><div class="settings-section-title"><h3>背景主题</h3></div><fieldset class="settings-card settings-close-options"><legend>软件外观</legend><label><input type="radio" name="zlTheme" value="system"><span><strong>跟随系统（默认）</strong><small>随电脑的浅色或深色主题自动切换。</small></span></label><label><input type="radio" name="zlTheme" value="light"><span><strong>浅色模式</strong></span></label><label><input type="radio" name="zlTheme" value="dark"><span><strong>深色模式</strong></span></label></fieldset><p class="settings-feedback" data-feedback="appearance" role="status"></p></section>
 <section data-settings-panel="activation"><div class="settings-section-title"><h3>激活信息</h3><span class="settings-badge">离线验证</span></div><p class="settings-description">当前使用固定 20 位激活码，在本机完成验证。</p><div class="settings-card"><dl class="settings-details"><div><dt>激活状态</dt><dd data-metric="offlineStatus">—</dd></div><div><dt>激活码</dt><dd>****************4E5</dd></div><div><dt>激活日期</dt><dd data-metric="offlineDate">—</dd></div><div><dt>验证方式</dt><dd>本机离线验证</dd></div><div><dt>授权范围</dt><dd>当前设备；不绑定硬件</dd></div><div><dt>联网复检</dt><dd>未启用</dd></div></dl></div><div class="settings-card"><h4>激活规则</h4><ol class="settings-rules"><li>首次启动输入固定 20 位激活码，验证通过后进入软件。</li><li>本机记住激活状态，后续启动自动读取并校验。</li><li>清除本地数据或更换使用环境后，需要重新输入激活码。</li></ol><p class="settings-caption">当前采用固定离线激活码，不支持远程停用或设备绑定。</p></div><div class="settings-actions"><button class="button blue" data-setting-action="verify">重新检查本机激活状态</button></div><p class="settings-feedback" data-feedback="activation" role="status"></p></section>
 <section data-settings-panel="local" hidden><div class="settings-section-title"><h3>本地设置</h3><span class="settings-badge">聊天记录与缓存</span></div><p class="settings-description">管理聊天记录保存与导出，查看译文缓存。</p>
 <div class="settings-card"><div class="settings-card-heading"><h4>译文缓存</h4><button class="button quiet" data-setting-action="refresh-cache">刷新</button></div><div class="settings-cache-metrics"><div><strong data-metric="cacheCount">0</strong><span>条示例译文</span></div><div><strong data-metric="cacheBytes">0 KB</strong><span>译文文本大小</span></div></div><p class="settings-caption">统计当前页面已生成的示例接收译文。真实翻译服务与磁盘缓存尚未接入。</p><button class="button quiet settings-clear-cache" data-setting-action="clear-cache">清理示例译文缓存</button><p class="settings-caption">仅清除示例译文，保留原消息、草稿、账号和客户备注。</p></div>
 <p class="settings-feedback" data-feedback="local" role="status"></p></section>
 <section data-settings-panel="performance" hidden><div class="settings-section-title"><h3>性能监控</h3><button class="button quiet" data-setting-action="refresh-performance">刷新</button></div><p class="settings-description">查看软件环境数量与当前页面运行情况。</p><div class="settings-monitor-banner"><div><small>监控状态</small><strong>桌面指标待接入</strong></div><span data-metric="updatedAt">—</span></div>
 <div class="settings-monitor-grid"><article class="settings-metric-card"><h4>CPU 占用</h4><strong>—</strong><p>等待桌面进程采样</p></article><article class="settings-metric-card"><h4>软件内存占用</h4><strong>—</strong><p>等待桌面进程采样</p></article><article class="settings-metric-card"><h4>已配置环境</h4><strong data-metric="accounts">0</strong><p data-metric="accountBreakdown">WhatsApp 0 · Facebook 0</p></article><article class="settings-metric-card"><h4>未休眠 / 已休眠</h4><strong data-metric="awake">0 / 0</strong><p>配置状态，不代表真实登录数</p></article><article class="settings-metric-card"><h4>当前页面 JS 堆内存</h4><strong data-metric="heap">—</strong><p>浏览器提供的估计值，非软件总内存</p></article><article class="settings-metric-card"><h4>当前页面运行时间</h4><strong data-metric="uptime">—</strong><p>仅统计本页面</p></article></div><p class="settings-caption">此页打开时每 2 秒刷新；浏览器不支持的指标显示“—”。</p></section>
 <section data-settings-panel="startup" hidden><div class="settings-section-title"><h3>开机启动</h3><span class="settings-badge pending">Windows 待接入</span></div><p class="settings-description">设置电脑启动并登录 Windows 后，是否自动启动 ZL。</p><div class="settings-card settings-switch-row"><div><h4>开机自动启动软件</h4><p class="settings-caption">开启后自动启动仍须通过激活验证。</p></div><label class="switch"><input type="checkbox" id="settingsAutoStart" aria-label="开机自动启动软件"><span></span></label></div><fieldset class="settings-card settings-close-options"><legend>关闭主窗口时</legend><label><input type="radio" name="closeBehavior" value="tray"><span><strong>最小化到系统托盘</strong><small>隐藏主窗口，保持软件在后台运行。</small></span></label><label><input type="radio" name="closeBehavior" value="exit"><span><strong>直接退出软件</strong><small>结束软件运行，停止后台任务。</small></span></label></fieldset><p class="settings-feedback" data-feedback="startup" role="status"></p><p class="settings-caption">设置自动保存。仅影响主窗口关闭按钮，不影响设置或转发窗口。Windows 桌面版应用开机启动和窗口关闭设置。</p></section>
 <section data-settings-panel="updates" hidden><div class="settings-section-title"><h3>软件更新</h3><span class="settings-badge pending">未配置发布源</span></div><p class="settings-description">在后台检查新版本，有更新时下载并安装升级。</p><div class="settings-card"><dl class="settings-details"><div><dt>当前版本</dt><dd>v${window.zlDesktop?.version||APP_VERSION}</dd></div><div><dt>版本类型</dt><dd>${window.zlDesktop?"Windows 桌面版":"网页版"}</dd></div><div><dt>最新版本</dt><dd>尚未检测</dd></div><div><dt>更新状态</dt><dd data-metric="updateStatus">等待连接更新服务</dd></div></dl><div class="settings-actions"><button class="button blue" data-setting-action="check-updates">后台检查更新</button><button class="button quiet" disabled title="检测到可用桌面更新后启用">下载并安装</button></div><p class="settings-feedback" data-feedback="updates" role="status"></p></div><div class="settings-card"><h4>在线升级流程</h4><p class="settings-description">检查版本 → 查看更新说明 → 后台下载 → 安装并重启</p><p class="settings-caption">升级前需要保存工作并校验更新包。更新服务尚未接入，当前不会下载或安装程序。</p></div></section>
 </div></div><footer class="system-settings-footer"><span>设置适用于整个 ZL Multi Manager</span><div><button type="button" class="settings-footer-link" data-setting-action="keys">翻译 API Key</button><button type="button" class="settings-footer-link" data-setting-action="help">使用说明</button></div></footer>`;
 document.body.append(dialog);const q=s=>dialog.querySelector(s),feedback=(tab,text,error=false)=>{const el=q('[data-feedback="'+tab+'"]');el.textContent=text;el.classList.toggle('error',error)};
 const historySettings=createHistorySettings(getHistoryAccounts);q('[data-settings-panel=local] .settings-card').before(historySettings.element);
 let prefs={autoStart:false,closeBehavior:'tray',cacheDirectory:''},timer=null,selectedTab='activation',opener=null;
 const safeStorage={getItem:key=>localStorage.getItem(key),setItem:(key,value)=>localStorage.setItem(key,value)};
 const labels=[['appearance','背景主题','settings'],['activation','激活信息','lock'],['local','本地设置','layers'],['performance','性能监控','sliders'],['startup','开机启动','power'],['updates','检查更新','refresh']];
 for(const [id,label,glyph]of labels){const b=element('button','settings-nav-button');b.type='button';b.dataset.settingsTab=id;b.innerHTML=icon(glyph,17);b.append(element('span','',label));b.onclick=()=>selectTab(id);q('nav').append(b)}
 q('.settings-head-icon').innerHTML=icon('settings',23);q('.settings-close').innerHTML=icon('close',18);
 function setMetric(key,value){q('[data-metric="'+key+'"]').textContent=value}
 function refreshActivation(){const record=readOfflineLicense(safeStorage);setMetric('offlineStatus',record?'已激活':'未激活');setMetric('offlineDate',record?new Date(record.activatedAt).toLocaleString('zh-CN',{hour12:false}):'—');return Boolean(record)}
 function refreshCache(){const stats=getCache();setMetric('cacheCount',stats.count);setMetric('cacheBytes',bytes(stats.bytes));q('[data-setting-action="clear-cache"]').disabled=!stats.count}
 function refreshPerformance(){const stats=getStats();setMetric('accounts',stats.total);setMetric('accountBreakdown','WhatsApp '+stats.whatsapp+' · Facebook '+stats.facebook);setMetric('awake',stats.awake+' / '+stats.sleeping);setMetric('heap',bytes(performance.memory?.usedJSHeapSize));const secs=Math.floor(performance.now()/1000);setMetric('uptime',Math.floor(secs/3600)+'时 '+Math.floor(secs%3600/60)+'分 '+secs%60+'秒');setMetric('updatedAt','更新于 '+new Date().toLocaleTimeString('zh-CN',{hour12:false}))}
 function selectTab(id){selectedTab=id;dialog.querySelectorAll('[data-settings-panel]').forEach(p=>p.hidden=p.dataset.settingsPanel!==id);dialog.querySelectorAll('[data-settings-tab]').forEach(b=>{const active=b.dataset.settingsTab===id;b.classList.toggle('active',active);if(active)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});q('.system-settings-content').scrollTop=0;if(id==='activation')refreshActivation();if(id==='local'){refreshCache();historySettings.refresh()}if(id==='performance')refreshPerformance()}
 function close(){dialog.close();return true}
 q('.settings-close').onclick=close;dialog.addEventListener('cancel',e=>{e.preventDefault();close()});dialog.addEventListener('close',()=>{clearInterval(timer);timer=null;opener?.focus()});
 dialog.querySelectorAll('[name=closeBehavior]').forEach(input=>input.onchange=()=>{if(!input.checked)return;try{prefs=savePreferences(safeStorage,{...prefs,closeBehavior:input.value});onPreferencesChange(prefs);feedback('startup','已保存：关闭主窗口时'+(prefs.closeBehavior==='exit'?'直接退出软件。':'最小化到系统托盘。'))}catch{dialog.querySelectorAll('[name=closeBehavior]').forEach(r=>r.checked=r.value===prefs.closeBehavior);feedback('startup','设置未能保存，请重试。',true)}});
 q('#settingsAutoStart').onchange=()=>{try{prefs=savePreferences(safeStorage,{...prefs,autoStart:q('#settingsAutoStart').checked});onPreferencesChange(prefs);feedback('startup',window.zlDesktop?'已提交 Windows 开机启动设置。':prefs.autoStart?'已保存开启偏好，尚未应用到 Windows。':'已保存关闭偏好，尚未应用到 Windows。')}catch{q('#settingsAutoStart').checked=prefs.autoStart;feedback('startup','设置未能保存，请重试。',true)}};
 dialog.querySelectorAll('[name=zlTheme]').forEach(input=>input.onchange=()=>{if(!input.checked)return;try{window.ZLTheme.set(input.value);feedback('appearance','主题已保存并应用')}catch{input.checked=false;feedback('appearance','主题保存失败，请重试',true)}});
 const actions={
 verify:()=>{const valid=refreshActivation();feedback('activation',valid?'本机激活状态有效，无需联网。':'本机激活记录无效，请重新打开软件并激活。',!valid)},
 'refresh-cache':refreshCache,
 'clear-cache':()=>{if(!window.confirm('清理当前页面的示例译文缓存？原消息、草稿、账号和客户备注会保留。'))return;clearCache();refreshCache();feedback('local','示例接收译文已清理，可在消息气泡内重新翻译。')},
 'refresh-performance':refreshPerformance,
 'check-updates':()=>{setMetric('updateStatus','检查未执行：发布源尚未配置');feedback('updates','尚未配置更新服务地址，无法获取最新版本或下载安装包。',true)},
 keys:()=>{if(close())onKeys()},help:()=>{if(close())onHelp()}
 };
 dialog.querySelectorAll('[data-setting-action]').forEach(b=>b.onclick=actions[b.dataset.settingAction]);
 return {open(){if(dialog.open)return;opener=document.activeElement;prefs=readPreferences(safeStorage);dialog.querySelectorAll('[name=zlTheme]').forEach(r=>r.checked=r.value===window.ZLTheme.get());q('#settingsAutoStart').checked=prefs.autoStart;dialog.querySelectorAll('[name=closeBehavior]').forEach(r=>r.checked=r.value===prefs.closeBehavior);dialog.querySelectorAll('[data-feedback]').forEach(e=>{e.textContent='';e.classList.remove('error')});dialog.showModal();selectTab(selectedTab);q('.settings-close').focus();timer=setInterval(()=>{if(selectedTab==='performance')refreshPerformance();if(selectedTab==='local')refreshCache()},2000)}};
}
